    vector<vector<long long>> balloons(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> balloons[i][j];
        }
    }

    sort(balloons.begin(), balloons.end(), [](const vector<long long>& x, const vector<long long>& y) { return x[1] < y[1]; });
    long long arrows = 0, shot = -1;
