import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] balloons = new long[(int) n][2];
        for (int i = 0; i < balloons.length; i++) {
            for (int j = 0; j < balloons[i].length; j++) {
                balloons[i][j] = Long.parseLong(next());
            }
        }

        int count = (int) n;
        long[] keys = new long[count];
        for (int i = 0; i < count; i++) keys[i] = (balloons[i][1] << 30) + balloons[i][0];
        Arrays.sort(keys);
        long arrows = 0, shot = -1;
        for (int i = 0; i < count; i++) {
            long b = keys[i] >> 30;
            long a = keys[i] & ((1L << 30) - 1);
            if (a > shot) {
                arrows++;
                shot = b;
            }
        }
        System.out.println(arrows);
    }
}
